contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanToCollateral_ != 0, "div0");
        uint256 requiredCollateral = c.collateralFor(amount_, loanToCollateral_);
        require(requiredCollateral != 0, "zero collat");

        uint256 reqCountBefore = c.requests.length;

        bool reverted;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            uint256 reqCountAfter = c.requests.length;
            assert(reqCountAfter == reqCountBefore);
        } else {
            uint256 reqCountAfter = c.requests.length;
            assert(reqCountAfter == reqCountBefore + 1);

            uint256 reqID = reqCountAfter - 1;
            C.Request memory req = c.getRequest(reqID);

            assert(req.amount == amount_);
            assert(req.interest == interest_);
            assert(req.loanToCollateral == loanToCollateral_);
            assert(req.duration == duration_);
            assert(req.active == true);
            assert(c.collateralFor(req.amount, req.loanToCollateral) == requiredCollateral);
        }
    }

    receive() external payable {}
}

