contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanToCollateral_ > 0, "div");

        // owner funds/approves collateral + debt for this test contract is not guaranteed,
        // so only exercise the part that does not require token movement to succeed:
        // create and settle a loan, then assert the defaulted-claim behavior.
        c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        bool cleared;
        try c.clearRequest(0, false, false) { cleared = true; } catch { cleared = false; }
        require(cleared, "clear failed");

        C.Loan memory loanBefore = c.getLoan(0);
        require(loanBefore.expiry >= block.timestamp, "bad expiry");

        // Burn time until the loan is expired (bounded loop avoids unbounded gas).
        uint256 expiry_ = loanBefore.expiry;
        while (block.timestamp <= expiry_) {
            // empty body: timed loop until expiry passes
        }

        uint256 beforeBalance = address(c).balance;
        (uint256 returnedAmount, uint256 returnedCollateral, uint256 expiryExcess) = c.claimDefaulted(0);

        assert(
            returnedAmount == loanBefore.amount &&
            returnedCollateral == loanBefore.collateral &&
            expiryExcess >= 1 &&
            address(c).balance == beforeBalance
        );
    }

    receive() external payable {}
}

