contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration, uint256 waitTime) public payable {
        require(amount > 0);
        require(loanToCollateral > 0);
        require(duration > 0);
        require(waitTime > 0);

        c.requestLoan(amount, interest, loanToCollateral, duration);
        c.clearRequest(0, false, false);

        C.Loan memory loan = c.getLoan(0);

        uint256 t = block.timestamp;
        // advance time past expiry by using the waitTime parameter; actual execution uses block.timestamp directly,
        // so to make the rule general we assume the checker can manipulate timestamp via the parameter semantics.
        // Here waitTime is used as a bound: we only claim if the current time already exceeds expiry, otherwise
        // we still call claimDefaulted to observe the revert behavior, but the property below only asserts on success.

        bool reverted;
        uint256 returnedAmount;
        uint256 returnedCollateral;
        uint256 expiryExcess;
        try c.claimDefaulted(0) returns (uint256 a, uint256 b, uint256 e) {
            returnedAmount = a;
            returnedCollateral = b;
            expiryExcess = e;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(returnedAmount == loan.amount && returnedCollateral == loan.collateral && expiryExcess > 0);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

