        require(a1, "approve failed");

        // Send some of the collateral to the owner on the cooler so it can be used if needed.
        (bool t1, ) = coll_.call(abi.encodeWithSignature("transfer(address,uint256)", owner_, collBalanceBorrower / 2));
        require(t1, "transfer failed");

        uint256 collBalBefore = collateralToken.balanceOf(coolerAddr);

        // The deciding call: requestLoan with the parameters.
        uint256 reqID = local.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        uint256 collBalAfter = collateralToken.balanceOf(coolerAddr);
        uint256 expectedCollateral = local.collateralFor(amount_, loanToCollateral_);

        // General rule: the new request ID is the next sequential index, and the collateral moved
        // into the cooler equals collateralFor(amount, loanToCollateral), while the request record
        // holds exactly the arguments passed.
        assert(
            reqID == preexisting &&
            collBalAfter == collBalBefore + expectedCollateral &&
            local.collateral() == collateralToken &&
            local.debt() == debtToken
        );
    }

    receive() external payable {}
}

